{"content": "1|//! GEMM kernel interface and configuration.
2|//!
3|//! Provides the core matmul abstraction used by the LLM inference engine.
4|//! Supports two architectures:
5|//! - WGMMA (sm_120, consumer Blackwell: RTX 5060 Ti / 5090)
6|//! - tcgen05 (sm_100, datacenter Blackwell: B200)
7|//!
8|//! The differentiator: proving tcgen05 matmul works for LLM workloads
9|//! with non-matrix layouts (KV cache updates: M:1×K, K:N×K shapes).
10|
11|use crate::kernel::device_buf::DeviceBuffer;
12|use half::f16;
13|
14|/// Tensor core architecture selection.
15|#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, serde::Serialize, serde::Deserialize)]
16|pub enum GemmArch {
17|    /// WGMMA — warpgroup matrix multiply (sm_90a, Hopper only)
18|    Wgmma,
19|    /// tcgen05 — tensor memory MMA (sm_100a/sm_103a, datacenter Blackwell)
20|    Tcgen05,
21|    /// mma.sync — classic warp-level tensor core MMA (sm_80..sm_120, incl.
22|    /// consumer Blackwell RTX 50-series, which has neither wgmma nor tcgen05)
23|    #[default]
24|    Mma,
25|}
26|
27|impl GemmArch {
28|    pub fn name(&self) -> &'static str {
29|        match self {
30|            Self::Wgmma => "wgmma",
31|            Self::Tcgen05 => "tcgen05",
32|            Self::Mma => "mma.sync",
33|        }
34|    }
35|
36|    pub fn supports_tma(&self) -> bool {
37|        // tcgen05 has native TMA support; WGMMA uses TMA for GMEM->SMEM copies
38|        match self {
39|            Self::Wgmma | Self::Tcgen05 => true,
40|            Self::Mma => false,
41|        }
42|    }
43|
44|    pub fn tile_size(&self) -> usize {
45|        match self {
46|            Self::Wgmma => 64,    // 64x64x64 tiles
47|            Self::Tcgen05 => 128, // 128x128x16 tiles
48|            Self::Mma => 16,      // 16x8x16 tiles
49|        }
50|    }
51|}
52|
53|/// Configuration for a GEMM kernel launch.
54|#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
55|pub struct GemmConfig {
56|    /// Target architecture
57|    pub arch: GemmArch,
58|    /// Whether to use TMA for async GMEM->SMEM copies
59|    pub use_tma: bool,
60|    /// Custom block size override (0 = use arch default)
61|    pub block_size: usize,
62|}
63|
64|impl Default for GemmConfig {
65|    fn default() -> Self {
66|        Self {
67|            arch: GemmArch::default(),
68|            use_tma: true,
69|            block_size: 0,
70|        }
71|    }
72|}
73|
74|impl GemmConfig {
75|    pub fn effective_block_size(&self) -> usize {
76|        if self.block_size > 0 {
77|            self.block_size
78|        } else {
79|            self.arch.tile_size()
80|        }
81|    }
82|
83|    pub fn with_arch(mut self, arch: GemmArch) -> Self {
84|        self.arch = arch;
85|        self
86|    }
87|
88|    pub fn with_tma(mut self, use_tma: bool) -> Self {
89|        self.use_tma = use_tma;
90|        self
91|    }
92|
93|    pub fn with_block_size(mut self, block_size: usize) -> Self {
94|        self.block_size = block_size;
95|        self
96|    }
97|}
98|
99|// --- GemmKernel Trait ---
100|
101|/// Trait for GEMM (matrix multiply) kernels.
102|///
103|/// Both GPU (CUDA) and CPU implementations implement this trait.
104|pub trait GemmKernel: Send + Sync {
105|    /// Perform GEMM: C = alpha * A @ B + beta * C
106|    fn matmul(
107|        &self,
108|        _alpha: f32,
109|        a: &DeviceBuffer<f16>,
110|        b: &DeviceBuffer<f16>,
111|        _beta: f32,
112|        c: &mut DeviceBuffer<f32>,
113|        m: usize,
114|        n: usize,
115|        k: usize,
116|    ) -> Result<(), GemmError>;
117|
118|    /// Check if the kernel is available on the current device.
119|    fn is_available(&self) -> bool;
120|
121|    /// Get the target architecture.
122|    fn arch(&self) -> GemmArch;
123|}
124|
125|// --- CPU Implementation (Fallback) ---
126|
127|/// Simple CPU GEMM implementation for testing and fallback.
128|pub struct CpuGemmKernel;
129|
130|impl CpuGemmKernel {
131|    pub fn new() -> Self {
132|        Self
133|    }
134|}
135|
136|impl Default for CpuGemmKernel {
137|    fn default() -> Self {
138|        Self::new()
139|    }
140|}
141|
142|impl GemmKernel for CpuGemmKernel {
143|    fn matmul(
144|        &self,
145|        alpha: f32,
146|        a: &DeviceBuffer<f16>,
147|        b: &DeviceBuffer<f16>,
148|        beta: f32,
149|        c: &mut DeviceBuffer<f32>,
150|        m: usize,
151|        n: usize,
152|        k: usize,
153|    ) -> Result<(), GemmError> {
154|        let a_host = a.as_slice().ok_or(GemmError::BufferSizeMismatch {
155|            expected: m * k,
156|            got: 0,
157|        })?;
158|        let b_host = b.as_slice().ok_or(GemmError::BufferSizeMismatch {
159|            expected: k * n,
160|            got: 0,
161|        })?;
162|        let c_host = c.as_mut_slice().ok_or(GemmError::BufferSizeMismatch {
163|            expected: m * n,
164|            got: 0,
165|        })?;
166|
167|        // Simple O(m*n*k) GEMM
168|        for i in 0..m {
169|            for j in 0..n {
170|                let mut sum = 0.0f32;
171|                for l in 0..k {
172|                    sum += a_host[i * k + l].to_f32() * b_host[l * n + j].to_f32();
173|                }
174|                c_host[i * n + j] = alpha * sum + beta * c_host[i * n + j];
175|            }
176|        }
177|
178|        Ok(())
179|    }
180|
181|    fn is_available(&self) -> bool {
182|        true
183|    }
184|
185|    fn arch(&self) -> GemmArch {
186|        GemmArch::default()
187|    }
188|}
189|
190|// --- GPU Implementation (Real cuda-oxide backed) ---
191|
192|#[cfg(feature = "cuda")]
193|use std::sync::Arc;
194|
195|#[cfg(feature = "cuda")]
196|/// CUDA implementation for GEMM kernel using cuda-oxide.
197|pub struct CudaGemmKernel {
198|    arch: GemmArch,
199|    context: Arc<cuda_core::CudaContext>,
200|    stream: Arc<cuda_core::CudaStream>,
201|    module: Arc<cuda_core::CudaModule>,
202|    function: cuda_core::CudaFunction,
203|}
204|
205|#[cfg(feature = "cuda")]
206|/// Builder for CudaGemmKernel that handles PTX loading and kernel resolution.
207|pub struct CudaGemmKernelBuilder {
208|    arch: GemmArch,
209|    context: Arc<cuda_core::CudaContext>,
210|    stream: Arc<cuda_core::CudaStream>,
211|    device_info: crate::cuda_runtime::CudaDeviceInfo,
212|}
213|
214|#[cfg(feature = "cuda")]
215|impl CudaGemmKernelBuilder {
216|    pub fn new(
217|        arch: GemmArch,
218|        context: Arc<cuda_core::CudaContext>,
219|        stream: Arc<cuda_core::CudaStream>,
220|        device_info: crate::cuda_runtime::CudaDeviceInfo,
221|    ) -> Self {
222|        Self {
223|            arch,
224|            context,
225|            stream,
226|            device_info,
227|        }
228|    }
229|
230|    /// Build the kernel by loading PTX module and resolving function.
231|    pub fn build(self) -> Result<CudaGemmKernel, GemmError> {
232|        // Pre-flight architecture check. mma.sync works on every tensor-core
233|        // GPU (sm_80..sm_120), so it needs no capability gate.
234|        match self.arch {
235|            GemmArch::Wgmma if !self.device_info.supports_wgmma() => {
236|                return Err(GemmError::UnsupportedArch(format!(
237|                    "WGMMA requires sm_90a (Hopper), but device is sm_{}.{}",
238|                    self.device_info.compute_capability.0, self.device_info.compute_capability.1
239|                )));
240|            }
241|            GemmArch::Tcgen05 if !self.device_info.supports_tcgen05() => {
242|                return Err(GemmError::UnsupportedArch(format!(
243|                    "tcgen05 requires sm_100a (datacenter Blackwell), but device is sm_{}.{}",
244|                    self.device_info.compute_capability.0, self.device_info.compute_capability.1
245|                )));
246|            }
247|            _ => {}
248|        }
249|
250|        // Select PTX based on architecture
251|        let ptx_src = match self.arch {
252|            GemmArch::Wgmma => include_str!("ptx/gemm_wgmma_real.ptx"),
253|            GemmArch::Tcgen05 => include_str!("ptx/gemm_tcgen05_real.ptx"),
254|            GemmArch::Mma => include_str!("ptx/gemm_mma_sync.ptx"),
255|        };
256|
257|        // Load module from PTX source
258|        let module = self
259|            .context
260|            .load_module_from_ptx_src(ptx_src)
261|            .map_err(|e| GemmError::Cuda(format!("module load failed: {e}")))?;
262|
263|        // Resolve kernel function
264|        let kernel_name = match self.arch {
265|            GemmArch::Wgmma => "gemm_wgmma_kernel",
266|            GemmArch::Tcgen05 => "gemm_tcgen05_kernel",
267|            GemmArch::Mma => "gemm_mma_kernel",
268|        };
269|        let function = module
270|            .load_function(kernel_name)
271|            .map_err(|e| GemmError::Cuda(format!("function load failed: {}", e)))?;
272|
273|        Ok(CudaGemmKernel {
274|            arch: self.arch,
275|            context: self.context,
276|            stream: self.stream,
277|            module,
278|            function,
279|        })
280|    }
281|}
282|
283|#[cfg(feature = "cuda")]
284|impl CudaGemmKernel {
285|    /// Get the cuda-oxide context for external operations
286|    pub fn context(&self) -> &Arc<cuda_core::CudaContext> {
287|        &self.context
288|    }
289|
290|    /// Get the cuda-oxide stream
291|    pub fn stream(&self) -> &Arc<cuda_core::CudaStream> {
292|        &self.stream
293|    }
294|
295|    /// Launch the GEMM kernel on the given streams.
296|    pub fn launch(
297|        &self,
298|        alpha: f32,
299|        a: &DeviceBuffer<f16>,
300|        b: &DeviceBuffer<f16>,
301|        beta: f32,
302|        c: &mut DeviceBuffer<f32>,
303|        m: usize,
304|        n: usize,
305|        k: usize,
306|    ) -> Result<(), GemmError> {
307|        use crate::cuda_runtime::CudaRuntime;
308|
309|        // Kernel signature (gemm_mma_sync.ptx):
310|        //   gemm_mma_kernel(f32 alpha, u64 A, u64 B, f32 beta,
311|        //                   u64 C, u32 m, u32 n, u32 k)
312|        // cuLaunchKernel wants one pointer per parameter, each pointing at a
313|        // host-side value of the exact kernel-parameter type. The u64 params
314|        // hold the device addresses as plain integers — do NOT pass the
315|        // device pointers themselves, or the driver dereferences them on the
316|        // host (segfault).
317|        let mut a_v: u64 = a.device_ptr();
318|        let mut b_v: u64 = b.device_ptr();
319|        let mut c_v: u64 = c.device_ptr();
320|        let mut alpha_v: f32 = alpha;
321|        let mut beta_v: f32 = beta;
322|        let mut m_v: u32 = m as u32;
323|        let mut n_v: u32 = n as u32;
324|        let mut k_v: u32 = k as u32;
325|        let mut params: [*mut libc::c_void; 8] = [
326|            &mut alpha_v as *mut f32 as *mut libc::c_void,
327|            &mut a_v as *mut u64 as *mut libc::c_void,
328|            &mut b_v as *mut u64 as *mut libc::c_void,
329|            &mut beta_v as *mut f32 as *mut libc::c_void,
330|            &mut c_v as *mut u64 as *mut libc::c_void,
331|            &mut m_v as *mut u32 as *mut libc::c_void,
332|            &mut n_v as *mut u32 as *mut libc::c_void,
333|            &mut k_v as *mut u32 as *mut libc::c_void,
334|        ];
335|
336|        // mma.sync kernel: one warp (32 threads) per 16x8 output tile.
337|        let grid = (
338|            ((n + 7) / 8) as u32,
339|            ((m + 15) / 16) as u32,
340|            1u32,
341|        );
342|        let block = (32u32, 1u32, 1u32);
343|
344|        // Launch: grid, block, shared_mem_bytes, stream, params
345|        unsafe {
346|            cuda_core::launch_kernel_on_stream(
347|                &self.function,
348|                grid,
349|                block,
350|                0, // shared_mem_bytes
351|                self.stream.as_ref(),
352|                &mut params,
353|            )
354|            .map_err(|e| GemmError::LaunchFailed(format!("kernel launch failed: {e}")))?;
355|        }
356|
357|        Ok(())
358|    }
359|}
360|
361|#[cfg(feature = "cuda")]
362|impl GemmKernel for CudaGemmKernel {
363|    fn matmul(
364|        &self,
365|        alpha: f32,
366|        a: &DeviceBuffer<f16>,
367|        b: &DeviceBuffer<f16>,
368|        beta: f32,
369|        c: &mut DeviceBuffer<f32>,
370|        m: usize,
371|        n: usize,
372|        k: usize,
373|    ) -> Result<(), GemmError> {
374|        self.launch(alpha, a, b, beta, c, m, n, k)
375|    }
376|
377|    fn is_available(&self) -> bool {
378|        true
379|    }
380|
381|    fn arch(&self) -> GemmArch {
382|        self.arch
383|    }
384|}
385|
386|// --- Error Types ---
387|
388|/// Errors that can occur during GEMM execution.
389|#[derive(Debug, thiserror::Error)]
390|pub enum GemmError {
391|    #[error("buffer size mismatch: expected {expected}, got {got}")]
392|    BufferSizeMismatch { expected: usize, got: usize },
393|
