{"content": "1|//! Single transformer layer: attention + feed-forward with RMSNorm.
2|//!
3|//! Llama-style layer:
4|//!   x = x + attn(RMSNorm(x), Wq, Wk, Wv, Wo)
5|//!   x = x + ffn(RMSNorm(x), W1, W2, W3)
6|//!
7|
8|#![allow(clippy::needless_range_loop, clippy::let_and_return)]
9|//! FFN uses SwiGLU: gate = x @ W1^T, up = x @ W3^T,
10|//!   output = silu(gate) * (up @ W2^T)
11|
12|use crate::transformer::linear::Linear;
13|use crate::transformer::rms_norm::RmsNorm;
14|use crate::transformer::rope::RopeConfig;
15|
16|/// SwiGLU activation: silu(x) * y
17|fn swiglu(x: &[f32], y: &[f32], size: usize) -> Vec<f32> {
18|    let mut output = vec![0.0f32; size];
19|    for i in 0..size {
20|        // silu(x) = x * sigmoid(x) = x / (1 + exp(-x))
21|        let sigmoid = if x[i] >= 0.0 {
22|            1.0 / (1.0 + (-x[i]).exp())
23|        } else {
24|            x[i] / (1.0 + x[i].exp())
25|        };
26|        output[i] = sigmoid * x[i] * y[i];
27|    }
28|    output
29|}
30|
31|/// Attention mechanism for a single transformer layer.
32|pub struct Attention {
33|    pub wq: Linear,
34|    pub wk: Linear,
35|    pub wv: Linear,
36|    pub wo: Linear,
37|    pub rope: RopeConfig,
38|    pub num_heads: usize,
39|    pub num_kv_heads: usize,
40|    pub head_dim: usize,
41|    pub kv_dim: usize, // num_kv_heads * head_dim
42|}
43|
44|impl Attention {
45|    pub fn new(
46|        wq: Linear,
47|        wk: Linear,
48|        wv: Linear,
49|        wo: Linear,
50|        head_dim: usize,
51|        num_heads: usize,
52|        num_kv_heads: usize,
53|    ) -> Self {
54|        let kv_dim = num_kv_heads * head_dim;
55|        Self {
56|            wq,
57|            wk,
58|            wv,
59|            wo,
60|            rope: RopeConfig::new(head_dim, 10000.0, 4096),
61|            num_heads,
62|            num_kv_heads,
63|            head_dim,
64|            kv_dim,
65|        }
66|    }
67|
68|    /// Compute scaled dot-product attention.
69|    ///
70|    /// input: [batch, embed_dim]
71|    /// Returns: [batch, embed_dim]
72|    pub fn forward(
73|        &self,
74|        x: &[f32],
75|        batch_size: usize,
76|        seq_len: usize,
77|        start_pos: usize,
78|    ) -> Vec<f32> {
79|        let embed_dim = self.num_heads * self.head_dim;
80|
81|        // Q/K/V projections
82|        let q = self.wq.forward(x, batch_size);
83|        let k = self.wk.forward(x, batch_size);
84|        let v = self.wv.forward(x, batch_size);
85|
86|        // Apply RoPE to Q and K
87|        let mut q_rope = q;
88|        let mut k_rope = k;
89|        self.rope
90|            .apply(&mut q_rope, &mut k_rope, self.num_heads, seq_len, start_pos);
91|
92|        // Scaled dot-product attention: softmax(Q @ K^T / sqrt(head_dim)) @ V
93|        let scale = 1.0 / (self.head_dim as f32).sqrt();
94|
95|        // Q: [batch, seq_len, num_heads, head_dim] → [batch*seq_len, num_heads*head_dim]
96|        // K: [batch, seq_len, num_heads, head_dim] → [batch*seq_len, num_heads*head_dim]
97|        // We compute attention per position in the batch
98|
99|        let mut output = vec![0.0f32; batch_size * seq_len * embed_dim];
100|
101|        for b in 0..batch_size {
102|            for pos in 0..seq_len {
103|                let q_idx = (b * seq_len + pos) * embed_dim;
104|                let mut attn_weights = vec![0.0f32; seq_len];
105|
106|                // Q @ K^T for this position
107|                for j in 0..seq_len {
108|                    let mut sum = 0.0f32;
109|                    for h in 0..self.num_heads {
110|                        let q_start = q_idx + h * self.head_dim;
111|                        let k_start = (b * seq_len + j) * self.kv_dim
112|                            + h / (self.num_heads / self.num_kv_heads) * self.head_dim;
113|                        for d in 0..self.head_dim {
114|                            sum += q_rope[q_start + d] * k_rope[k_start + d];
115|                        }
116|                    }
117|                    attn_weights[j] = sum * scale;
118|                }
119|
120|                // Softmax
121|                let max_val = attn_weights
122|                    .iter()
123|                    .cloned()
124|                    .fold(f32::NEG_INFINITY, f32::max);
125|                let exps: Vec<f32> = attn_weights.iter().map(|w| (*w - max_val).exp()).collect();
126|                let exp_sum: f32 = exps.iter().sum();
127|                let softmax_out: Vec<f32> = if exp_sum > 0.0 {
128|                    exps.iter().map(|e| e / exp_sum).collect()
129|                } else {
130|                    vec![1.0 / seq_len as f32; seq_len]
131|                };
132|
133|                // softmax_out @ V
134|                let mut attn_output = vec![0.0f32; self.num_heads * self.head_dim];
135|                for h in 0..self.num_heads {
136|                    let group = h / (self.num_heads / self.num_kv_heads);
137|                    for d in 0..self.head_dim {
138|                        let mut sum = 0.0f32;
139|                        for j in 0..seq_len {
140|                            let v_start =
141|                                (b * seq_len + j) * self.kv_dim + group * self.head_dim + d;
142|                            sum += softmax_out[j] * v[v_start];
143|                        }
144|                        attn_output[h * self.head_dim + d] = sum;
145|                    }
146|                }
147|
148|                // Output projection: attn_output @ wo^T
149|                let wo_output = self.wo.forward(&attn_output, 1);
150|                for i in 0..embed_dim {
151|                    output[(b * seq_len + pos) * embed_dim + i] = wo_output[i];
152|                }
153|            }
154|        }
155|
156|        // Add residual: output = output + x (but we need to accumulate, not replace)
157|        // Actually the caller handles residual in the layer
158|        output
159|    }
160|}
161|
162|/// Feed-forward network with SwiGLU activation.
163|pub struct FeedForward {
164|    pub w1: Linear,
165|    pub w2: Linear,
166|    pub w3: Linear,
167|    pub intermediate_dim: usize,
168|}
169|
170|impl FeedForward {
171|    pub fn new(w1: Linear, w2: Linear, w3: Linear, intermediate_dim: usize) -> Self {
172|        Self {
173|            w1,
174|            w2,
175|            w3,
176|            intermediate_dim,
177|        }
178|    }
179|
180|    /// Forward pass: silu(x @ W1^T) * (x @ W3^T) @ W2^T
181|    pub fn forward(&self, x: &[f32], batch_size: usize) -> Vec<f32> {
182|        let gate = self.w1.forward(x, batch_size);
183|        let up = self.w3.forward(x, batch_size);
184|
185|        let swiglu_out = swiglu(&gate, &up, self.intermediate_dim);
186|        let output = self.w2.forward(&swiglu_out, batch_size);
187|
188|        output
189|    }
190|}
191|
192|/// Single transformer layer.
193|pub struct TransformerLayer {
194|    pub attention: Attention,
195|    pub feed_forward: FeedForward,
196|    pub attention_norm: RmsNorm,
197|    pub ffn_norm: RmsNorm,
198|}
199|
200|impl TransformerLayer {
201|    pub fn new(
202|        attention: Attention,
203|        feed_forward: FeedForward,
204|        attention_norm: RmsNorm,
205|        ffn_norm: RmsNorm,
206|    ) -> Self {
207|        Self {
208|            attention,
209|            feed_forward,
210|            attention_norm,
211|            ffn_norm,
212|        }
213|    }
214|
215|    /// Forward pass through one transformer layer.
216|    ///
217|    /// input: [batch, embed_dim]
218|    /// Returns: [batch, embed_dim] with residual connections applied
219|    pub fn forward(
220|        &self,
221|        x: &[f32],
222|        batch_size: usize,
223|        seq_len: usize,
224|        start_pos: usize,
225|    ) -> Vec<f32> {
226|        let embed_dim = x.len() / batch_size;
227|
228|        // Attention sub-layer: x + attn(RMSNorm(x))
229|        let normed = self.attention_norm.forward(x, batch_size);
230|        let attn_out = self
231|            .attention
232|            .forward(&normed, batch_size, seq_len, start_pos);
233|
234|        // Residual: x + attn_out
235|        let mut h = vec![0.0f32; batch_size * embed_dim];
236|        for i in 0..h.len() {
237|            if i >= x.len() || i >= attn_out.len() {
238|                break;
239|            }
240|            h[i] = x[i] + attn_out[i];
241|        }
242|
243|        // FFN sub-layer: h + ffn(RMSNorm(h))
244|        let normed_ffn = self.ffn_norm.forward(&h, batch_size);
245|        let ffn_out = self.feed_forward.forward(&normed_ffn, batch_size);
246|
247|        // Residual: h + ffn_out
248|        for i in 0..h.len() {
249|            h[i] += ffn_out[i];
250|        }
251|
252|        h
253|    }
254|}
