922|
923|    /// Run the model on a single token input.
924|    ///
925|    /// `token` — input token ID
926|    /// `start_pos` — position in the sequence (for RoPE)
927|    /// Returns: logits over vocabulary [vocab_size]
928|    pub fn forward(&self, token: u32, start_pos: usize) -> Result<Vec<f32>> {
929|        let logits = self.embed(token, start_pos)?;
930|        self.apply_output_head(&logits)
931|    }
932|
933|    /// Embed a single token ID into its embedding vector.
934|    pub fn embed(&self, token: u32, _start_pos: usize) -> Result<Vec<f32>> {
935|        let emb = self
936|            .token_embeddings
937|            .as_ref()
938|            .ok_or_else(|| RunnerError::ModelLoad("missing token embeddings".to_string()))?;
939|
940|        let token_idx = token as usize;
941|        // For 1D embedding tensors (shape [N]), the embedding dimension is the tensor length.
942|        // For 2D tensors (shape [vocab_size, embed_dim]), use in_features.
943|        let emb_dim = if emb.in_features == 1 && emb.out_features > 1 {
944|            // 1D tensor stored as [1, N] — the actual dim is out_features
945|            emb.out_features
946|        } else {
947|            emb.in_features
948|        };
949|        let start = token_idx * emb_dim;
950|        let x = emb.weight[start..start + emb_dim].to_vec();
951|        Ok(x)
952|    }
953|
954|    /// Apply the output (LM head) to get logits from hidden states.
955|    pub fn apply_output_head(&self, hidden: &[f32]) -> Result<Vec<f32>> {
956|        let output = self
957|            .output
958|            .as_ref()
959|            .ok_or_else(|| RunnerError::ModelLoad("missing output layer".to_string()))?;
960|
961|        let logits = output.forward(hidden, 1);
962|        Ok(logits)
963|    }
964|
965|    /// Pass hidden states through all transformer layers.
966|    pub fn forward_layers(&self, hidden: &[f32], start_pos: usize) -> Result<Vec<f32>> {
967|        let _embed_dim = hidden.len();
968|        let mut h = hidden.to_vec();
969|
970|        for (layer_idx, layer) in self.layers.iter().enumerate() {
971|            h = layer.forward(&h, 1, 1, start_pos); // Fixed: was start_pos + layer_idx
972|        }
973|
974|        // Apply final norm for architectures that have it (qwen2/qwen3)
975|        if let Some(ref norm) = self.final_norm {
976|            h = norm.forward(&h, 1);
977|        }
978|
979|        Ok(h)
980|    }
981|
982|    /// Pass hidden states through all layers using GPU dispatch (if available).
983|    ///
984|    /// Builds `LayerDispatch` from the model's weights and runs through each
985|    /// layer using the dispatch context. Falls back to CPU if GPU is unavailable.
986|    ///
987|    /// KV caches are initialized on first call and persist across calls.
988|    pub fn forward_with_dispatch(&mut self, hidden: &[f32], start_pos: usize) -> Result<Vec<f32>> {
989|        let ctx = self
990|            .dispatch
991|            .as_ref()
992|            .ok_or_else(|| RunnerError::Tensor("dispatch context not initialized".into()))?;
993|
994|        // Initialize KV caches on first call
995|        if self.kv_caches.is_none() {
996|            let mut key_caches = Vec::with_capacity(self.config.num_layers);
997|            let mut value_caches = Vec::with_capacity(self.config.num_layers);
998|            for _ in 0..self.config.num_layers {
999|                let key_cache = Kvcache::new(
1000|                    self.config.num_heads,
1001|                    self.config.num_kv_heads,
1002|                    self.config.head_dim,
1003|                    self.config.max_seq_len,
1004|                    if ctx.gpu_available() { true } else { false },
1005|                );
1006|                let value_cache = Kvcache::new(
1007|                    self.config.num_heads,
1008|                    self.config.num_kv_heads,
1009|                    self.config.head_dim,
1010|                    self.config.max_seq_len,
1011|                    if ctx.gpu_available() { true } else { false },
1012|                );
1013|                key_caches.push(key_cache);
1014|                value_caches.push(value_cache);
1015|            }
1016|            self.kv_caches = Some((key_caches, value_caches));
1017|        }
1018|
1019|        let (key_caches, value_caches) = self
1020|            .kv_caches
1021|            .as_mut()
1022|            .ok_or_else(|| RunnerError::Tensor("kv caches not initialized".into()))?;
1023|
1024|        let mut h = hidden.to_vec();
1025|
1026|        for (layer_idx, layer) in self.layers.iter().enumerate() {
1027|            // Build LayerDispatch from this layer's weights
1028|            let attention_dispatch = crate::kernel::dispatch::AttentionDispatch {
1029|                wq: crate::kernel::dispatch::LinearDispatch::new(
1030|                    f32_to_f16(&layer.attention.wq.weight),
1031|                    layer.attention.wq.weight.clone(),
1032|                    layer.attention.wq.bias.clone(),
1033|                    layer.attention.wq.in_features,
1034|                    layer.attention.wq.out_features,
1035|                ),
1036|                wk: crate::kernel::dispatch::LinearDispatch::new(
1037|                    f32_to_f16(&layer.attention.wk.weight),
1038|                    layer.attention.wk.weight.clone(),
1039|                    layer.attention.wk.bias.clone(),
1040|                    layer.attention.wk.in_features,
1041|                    layer.attention.wk.out_features,
1042|                ),
1043|                wv: crate::kernel::dispatch::LinearDispatch::new(
1044|                    f32_to_f16(&layer.attention.wv.weight),
1045|                    layer.attention.wv.weight.clone(),
1046|                    layer.attention.wv.bias.clone(),
1047|                    layer.attention.wv.in_features,
1048|                    layer.attention.wv.out_features,
1049|                ),
1050|                wo: crate::kernel::dispatch::LinearDispatch::new(
1051|                    f32_to_f16(&layer.attention.wo.weight),
1052|                    layer.attention.wo.weight.clone(),
1053|                    layer.attention.wo.bias.clone(),
1054|                    layer.attention.wo.in_features,
1055|                    layer.attention.wo.out_features,
1056|                ),
1057|                num_heads: layer.attention.num_heads,
1058|                num_kv_heads: layer.attention.num_kv_heads,
1059|                head_dim: layer.attention.head_dim,
1060|                kv_dim: layer.attention.kv_dim,
1061|            };
1062|
1063|            let feed_forward_dispatch = crate::kernel::dispatch::FeedForwardDispatch {
1064|                w1: crate::kernel::dispatch::LinearDispatch::new(
1065|                    f32_to_f16(&layer.feed_forward.w1.weight),
1066|                    layer.feed_forward.w1.weight.clone(),
1067|                    layer.feed_forward.w1.bias.clone(),
1068|                    layer.feed_forward.w1.in_features,
1069|                    layer.feed_forward.w1.out_features,
1070|                ),
1071|                w2: crate::kernel::dispatch::LinearDispatch::new(
1072|                    f32_to_f16(&layer.feed_forward.w2.weight),
