2|//!
3|//! Stores weight matrix in row-major layout: W[i][j] = weights[i * out_features + j].
4|//! Input x is [batch, in_features], output y is [batch, out_features].
5|//!
6|
7|#![allow(clippy::redundant_closure)]
8|
9|#[derive(Debug, Clone)]
10|pub struct Linear {
11|    pub weight: Vec<f32>,
12|    pub bias: Option<Vec<f32>>,
13|    pub in_features: usize,
14|    pub out_features: usize,
15|}
16|
17|impl Linear {
18|    pub fn new(
19|        weight: Vec<f32>,
20|        bias: Option<Vec<f32>>,
21|        in_features: usize,
22|        out_features: usize,
23|    ) -> Self {
24|        Self {
25|            weight,
26|            bias,
27|            in_features,
28|            out_features,
29|        }
30|    }
31|
32|    pub fn from_f16_weight(weight_f16: &[u8], bias: Option<Vec<f32>>) -> Self {
33|        let elements = weight_f16.len() / 2;
34|        let weight: Vec<f32> = weight_f16
35|            .chunks_exact(2)
36|            .map(|chunk| f16_to_f32(chunk))
37|            .collect();
38|        let (in_features, out_features) = if elements > 0 { (1, elements) } else { (0, 0) };
39|        Self {
40|            weight,
41|            bias,
42|            in_features,
43|            out_features,
44|        }
45|    }
46|
47|    /// Build a Linear layer from f32 bytes with explicit shape (preferred).
48|    ///
49|    /// Use this instead of `from_f32_weight` for attention/FFN weights where
50|    /// `in_features > 1`. The shape-less variant defaults `in_features=1`,
51|    /// which is only correct for 1D embedding lookups.
52|    pub fn from_f32_weight_with_dims(
53|        weight_f32: &[u8],
54|        bias: Option<Vec<f32>>,
55|        in_features: usize,
56|        out_features: usize,
57|    ) -> Self {
58|        let weight: Vec<f32> = weight_f32
59|            .chunks_exact(4)
60|            .map(|chunk| f32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]))
61|            .collect();
62|        Self {
63|            weight,
64|            bias,
65|            in_features,
66|            out_features,
67|        }
68|    }
69|
70|    /// Build a Linear layer from f32 bytes (used for safetensors loading).
71|    ///
72|    /// **Note:** Defaults `in_features=1`, which is only correct for 1D
73|    /// embedding tensors. For attention/FFN weights, use
74|    /// `from_f32_weight_with_dims` or `from_f32_weight_with_shape` instead.
75|    pub fn from_f32_weight(weight_f32: &[u8], bias: Option<Vec<f32>>) -> Self {
76|        let elements = weight_f32.len() / 4;
77|        let weight: Vec<f32> = weight_f32
78|            .chunks_exact(4)
79|            .map(|chunk| f32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]))
80|            .collect();
81|        let (in_features, out_features) = if elements > 0 { (1, elements) } else { (0, 0) };
82|        Self {
83|            weight,
84|            bias,
85|            in_features,
86|            out_features,
87|        }
88|    }
89|
90|    /// Build a Linear layer with explicit shape (for embeddings where we know embed_dim).
91|    pub fn from_f32_weight_with_shape(weight_f32: &[u8], bias: Option<Vec<f32>>, in_features: usize, out_features: usize) -> Self {
92|        let weight: Vec<f32> = weight_f32
93|            .chunks_exact(4)
94|            .map(|chunk| f32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]))
95|            .collect();
96|        Self {
97|            weight,
98|            bias,
99|            in_features,
100|            out_features,
101|        }
102|    }
103|
104|    /// Forward pass: y = x @ W^T + bias.
105|    ///
106|    /// x: [batch_size, in_features]
107|    /// Returns: [batch_size, out_features]
108|    pub fn forward(&self, x: &[f32], batch_size: usize) -> Vec<f32> {
109|        let mut output = vec![0.0f32; batch_size * self.out_features];
110|
111|        // Use gemm crate for optimized matrix multiplication: C = alpha*A*B + beta*C
112|        // We want: output = x @ W^T, where x is [batch, in_features] and W is [out_features, in_features]
113|        // gemm expects: C := alpha*A*B + beta*C where A is [m,k], B is [k,n], C is [m,n]
114|        // So we set: m=batch_size, n=out_features, k=in_features
115|        //           A=x (row-major), B=weight^T (so B[j,k] = weight[k*j + j]... wait, let's be careful)
116|        //
117|        // Actually, our weight layout is row-major: W[i][j] = weight[i * in_features + j]
118|        // So W^T[j][i] = W[i][j] = weight[i * in_features + j]
119|        // In gemm's column-major convention with transposition, we can use B = weight directly
120|        // and set conj_rhs=false, which effectively treats it as row-major.
121|        
122|        let m = batch_size;
123|        let n = self.out_features;
124|        let k = self.in_features;
125|
126|        if m == 0 || n == 0 || k == 0 {
127|            return output;
128|        }
129|
130|        // Call gemm::gemm with f32:
131|        // dst=output, lhs=x, rhs=weight
132|        // alpha=1.0, beta=0.0 (we want C = A*B, not C = A*B + C)
133|        // Since our weight is row-major and gemm expects column-major by default,
134|        // we use the transpose interpretation: B's rows become columns
135|        unsafe {
136|            gemm::gemm(
137|                m, n, k,
138|                output.as_mut_ptr(), 1_isize, (n as isize).neg(),  // C: row-major layout
139|                true,  // read_dst=false (beta=0)
140|                x.as_ptr(), 1_isize, (k as isize),  // A: [m,k] row-major
141|                k as isize, 1_isize,  // B: [k,n] treated as transposed = weight^T
142|                k as isize, 1_isize,
143|                1.0f32, 0.0f32,  // alpha=1, beta=0
144|                false, false, false,  // no conjugates
145|                gemm::Parallelism::Rayon(0),  // use all threads
146|            );
147|        }
148|
149|        // Apply bias if present
150|        if let Some(ref bias) = self.bias {
151|            for b in 0..batch_size {
152|                for o in 0..self.out_features {
153|                    output[b * self.out_features + o] += bias[o];
154|                }
155|            }
156|        }
157|
158|        output
159|    }
160|
161|    /// Matrix multiply: C = A @ B^T, where A is [m x k] and B is [n x k].
162|    pub fn matmul_transpose_b(a: &[f32], b: &[f32], m: usize, n: usize, k: usize) -> Vec<f32> {
163|        let mut c = vec![0.0f32; m * n];
164|        for i in 0..m {
165|            for j in 0..n {
166|                let mut sum = 0.0f32;
167|                for l in 0..k {
168|                    sum += a[i * k + l] * b[j * k + l];
169|                }
170|                c[i * n + j] = sum;
171|            }
172|        }
173|        c
174|    }
175|}
