177|/// Convert half-float bytes to f32.
178|fn f16_to_f32(bytes: &[u8]) -> f32 {
179|    let bits = u16::from_le_bytes([bytes[0], bytes[1]]);
180|    let sign = ((bits >> 15) & 1) as u32;
181|    let exp = ((bits >> 10) & 0x1F) as i32;
182|    let frac = (bits & 0x3FF) as u32;
183|
184|    if exp == 0 {
185|        if frac == 0 {
186|            f32::from_bits(sign << 31)
187|        } else {
188|            let f32_bits = (sign << 31) | (frac << 13);
189|            f32::from_bits(f32_bits)
190|        }
191|    } else if exp == 31 {
192|        f32::from_bits((sign << 31) | (0xFF << 23) | (frac << 13))
193|    } else {
194|        let f32_exp = (exp - 15 + 127) as u32;
195|        let f32_bits = (sign << 31) | (f32_exp << 23) | (frac << 13);
196|        f32::from_bits(f32_bits)
197|    }
198|}
